Proof using AF GP FKC SM4 SCR0 SSQ SGC SGS MSV2 SRC SS PCPY CSC SAD2 ACCFMT.
Ltac split_rows H := lazymatch type of H with
    | Forall _ (_ :: _) => let T := fresh "TR" in pose proof (Forall_inv H) as T; cbn [fst snd po_row app] in T;
                          let H2 := fresh "RW" in pose proof (Forall_inv_tail H) as H2; clear H; split_rows H2
    | _ => clear H end.
Ltac lres_pm :=
    unfold lres; repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end; cbn [length]; unfold FRAMES_MAX, LIVE_MAX in *;
    unfold CSC_COST, MCS_COST in *; unfold RC1 in *; unfold RASTER_COST in *;
    split; [repeat match goal with H : context [length (rt_frames _ _)] |- _ => revert H end; clear; intros; lia|];
    split; [lazymatch goal with |- Z.of_nat (length ?L) + _ <= _ =>
              match goal with LEN : Z.of_nat (length L) <= _ |- _ => revert LEN end; match goal with LB : Z.of_nat (length (rt_live _ _)) + _ <= _ |- _ => revert LB end;
              clear; intros; lia end|];
    split; [repeat match goal with H : context [rt_credit _ _] |- _ => revert H end; clear; intros; lia|];
    lazymatch goal with |- forall p n, In (p, n) ?L -> 0 < n => match goal with LP : forall q k, In (q, k) L -> 0 < k |- _ => exact LP end end.
Ltac after_call_unfold ::= unfold lpost, lpost_f, keeps, keepsL in *; cbn [p_w p_h p_d p_spp p_wpl p_xres p_yres p_inf p_spec p_cmap p_data c_arr c_depth c_nalloc c_n] in *.
Ltac after_call_open RT :=
    cps_open RT; after_call_unfold; fold_zdefs; unfold rt_after, rt_after_f in *; split_hyps; unfold SEGTOP_A, STACK_WIN, USTACK_TOP, RT_STACK in *;
    repeat match goal with H : context [bv_unsigned (Z_to_bv 64 ?e)] |- _ => rewrite (unsigned_lit e) in H by lia end;
    lazymatch goal with
    | P : rt_pres ?lv ?frs ?spc ?ma ?mb |- _ =>
        let AG := fresh "AG" in assert (AG : agree_on (aclient lv frs spc) ma mb) by (intros ? Ha; exact (P _ Ha)); clear P
    | P : rt_pres_fp ?lv ?frs ?spc ?W ?ma ?mb |- _ =>
        let AG := fresh "AG" in assert (AG : agree_on (fun a => aclient lv frs spc a /\ outside W a) ma mb) by (intros ? [Ha Hb]; exact (P _ Ha Hb)); clear P
    end.
Ltac tr_cell AG H side :=
    lazymatch type of AG with agree_on _ ?ma ?mb =>
      lazymatch type of H with rw_cells _ _ ?A ?cs =>
        apply (rw_cells_agree_nw asegs ma mb A cs) in H;
        [| let a := fresh "a" in let Ha := fresh "Ha" in intros a Ha; cbn [cells_size csize Nat.add length Z.of_nat Pos.of_succ_nat Pos.succ] in Ha; apply AG; side Ha ] end end.
Ltac drop_old ma := repeat match goal with
    | H : acc asegs ma _ _ |- _ => clear H | H : mem_inv asegs ma |- _ => clear H | H : stk asegs ma _ _ |- _ => clear H
    | H : munch _ _ ma |- _ => clear H | H : wmono asegs _ ma |- _ => clear H
    | H : rw_cells asegs ma _ _ |- _ => fail 100 "leftover cell (add a tr_cell case):" H | H : ro_cells asegs ma _ _ |- _ => clear H | H : bytes_at asegs ma _ _ |- _ => clear H end.
Ltac fixbr := lazymatch goal with |- evt _ _ (MS _ _ (if ?c then ?a else ?b) _ _ _ _) =>
    first [ replace (if c then a else b) with b by (vm_compute; reflexivity) | replace (if c then a else b) with a by (vm_compute; reflexivity) ] end.
Ltac fwalk stops := repeat (tryif at_stop stops then fail else first [ fixbr | cwalk1 ]).
Ltac after_call_unfold ::= unfold lpost, lpost_f, keeps, keepsL in *; cbn [p_w p_h p_d p_spp p_wpl p_xres p_yres p_inf p_spec p_cmap p_data c_arr c_depth c_nalloc c_n] in *.
Ltac after_call_open2 RT :=
    cps_open RT; after_call_unfold; fold_zdefs; unfold rt_after, rt_after_f in *; split_hyps; unfold SEGTOP_A, STACK_WIN, USTACK_TOP, RT_STACK in *;
    repeat match goal with H : context [bv_unsigned (Z_to_bv 64 ?e)] |- _ => rewrite (unsigned_lit e) in H by lia end;
    lazymatch goal with
    | P : rt_pres ?lv ?frs ?spc ?ma ?mb |- _ =>
        let AG := fresh "AG" in assert (AG : agree_on (aclient lv frs spc) ma mb) by (intros ? Ha; exact (P _ Ha)); clear P
    | P : rt_pres_ex ?lv ?frs ?spc ?d ?n ?ma ?mb |- _ =>
        let AG := fresh "AG" in assert (AG : agree_on (fun a => aclient lv frs spc a /\ ~ (d <= a < d + n)) ma mb) by (intros ? [Ha Hb]; exact (P _ Ha Hb)); clear P
    | P : rt_pres_fp ?lv ?frs ?spc ?W ?ma ?mb |- _ =>
        let AG := fresh "AG" in assert (AG : agree_on (fun a => aclient lv frs spc a /\ outside W a) ma mb) by (intros ? [Ha Hb]; exact (P _ Ha Hb)); clear P
    end.
ltac2:(KReplay.run1 (kr_t_Po_pmcs_c0 ()) ["PMCSC"] (String.concat "" [kr_b_Po_pmcs_c0_1_1 (); kr_b_Po_pmcs_c0_1_2 ()])). Qed.

